// src/pages/MentorPage.jsx
import React, { useState } from "react";
import NetworkBackground from "../components/NetworkBackground";

const expertiseTabs = [
  "Software Engineering",
  "Product Management",
  "Data Science",
  "Marketing",
  "Design",
];

const mentorProfiles = [
  {
    name: "Fatima Khan",
    role: "Software Engineering",
    image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80",
  },
  {
    name: "Benjamin Hayes",
    role: "Product Management",
    image: "https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=300&q=80",
  },
  {
    name: "Aisha Rahman",
    role: "Data Science",
    image: "https://images.unsplash.com/photo-1524504388940-b1c1722653e1?w=300&q=80",
  },
  {
    name: "Samuel Reed",
    role: "Marketing",
    image: "https://images.unsplash.com/photo-1552053566-35c9e1e96c79?w=300&q=80",
  },
  {
    name: "Zainab Malik",
    role: "Design",
    image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80",
  },
  {
    name: "Elijah Bennett",
    role: "Software Engineering",
    image: "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=300&q=80",
  },
  {
    name: "Nadia Ali",
    role: "Product Management",
    image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80",
  },
  {
    name: "Grayson Cole",
    role: "Data Science",
    image: "https://images.unsplash.com/photo-1552053566-35c9e1e96c79?w=300&q=80",
  },
  {
    name: "Aaliyah Siddiqui",
    role: "Marketing",
    image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80",
  },
  {
    name: "Jackson Reed",
    role: "Design",
    image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80",
  },
  {
    name: "Hafsa Ahmed",
    role: "Software Engineering",
    image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80",
  },
  {
    name: "Carter Hayes",
    role: "Product Management",
    image: "https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=300&q=80",
  },
  {
    name: "Mariam Hassan",
    role: "Data Science",
    image: "https://images.unsplash.com/photo-1524504388940-b1c1722653e1?w=300&q=80",
  },
  {
    name: "Henry Cole",
    role: "Marketing",
    image: "https://images.unsplash.com/photo-1552053566-35c9e1e96c79?w=300&q=80",
  },
  {
    name: "Lina Ibrahim",
    role: "Design",
    image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80",
  },
];

export default function MentorPage() {
  const [search, setSearch] = useState("");
  const [activeExpertise, setActiveExpertise] = useState("Software Engineering");

  const filteredProfiles = mentorProfiles.filter((m) => {
    const text = (m.name + " " + m.role).toLowerCase();
    const q = search.toLowerCase();
    const matchesSearch = !q || text.includes(q);
    const matchesExpertise = activeExpertise ? m.role === activeExpertise : true;
    return matchesSearch && matchesExpertise;
  });

  return (
    <div className="relative min-h-screen bg-white">
      {/* animated dots/lines background */}
      <NetworkBackground />

      <main className="relative z-10 max-w-6xl mx-auto px-4 pt-10 pb-24 xl:px-0">
        {/* Top search bar (under navbar) */}
        <section className="mb-6">
          <input
            type="text"
            placeholder="Search mentors by name or expertise"
            className="w-full rounded-full border border-gray-200 bg-white px-5 py-3 text-sm outline-none focus:ring-2 focus:ring-emerald-200"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </section>

        {/* Expertise tabs */}
        <section className="mb-6">
          <div className="flex flex-wrap gap-2">
            {expertiseTabs.map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveExpertise(tab)}
                className={`px-4 py-1.5 rounded-full text-xs font-medium border ${
                  activeExpertise === tab
                    ? "bg-emerald-500 text-white border-emerald-500"
                    : "bg-gray-50 text-gray-700 border-gray-200 hover:bg-gray-100"
                }`}
              >
                {tab}
              </button>
            ))}
          </div>
        </section>

        {/* Mentors avatar grid card */}
        <section className="mb-12">
          <div className="bg-white/95 rounded-3xl shadow-sm border border-gray-100 px-6 sm:px-8 pt-8 pb-6">
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-x-10 gap-y-8 mb-6">
              {filteredProfiles.map((m) => (
                <div key={m.name} className="flex flex-col items-center text-center">
                  <div className="w-24 h-24 rounded-full overflow-hidden mb-3 shadow-sm">
                    <img
                      src={m.image}
                      alt={m.name}
                      className="w-full h-full object-cover"
                    />
                  </div>
                  <div className="text-sm font-semibold">{m.name}</div>
                  <div className="text-[11px] text-gray-500">{m.role}</div>
                </div>
              ))}
            </div>

            <div className="flex flex-col sm:flex-row justify-center gap-4">
              <button className="px-6 py-2 rounded-full bg-emerald-500 text-white text-sm font-semibold hover:bg-emerald-600">
                Request Mentorship
              </button>
              <button className="px-6 py-2 rounded-full bg-gray-100 text-gray-800 text-sm font-semibold border border-gray-200 hover:bg-gray-200">
                View Profile
              </button>
            </div>
          </div>
        </section>

        {/* For Mentorship bottom card */}
        <section>
          <div className="bg-white/95 rounded-3xl shadow-sm border border-gray-100 px-6 sm:px-10 py-8 md:py-10 flex flex-col md:flex-row gap-8 items-center">
            <div className="md:w-1/2 flex justify-center">
              <div className="rounded-2xl overflow-hidden bg-emerald-50 max-w-xs w-full">
                <img
                  src="https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=500&q=80"
                  alt="Mentor"
                  className="w-full h-full object-cover"
                />
              </div>
            </div>
            <div className="md:w-1/2 w-full">
              <h2 className="text-xl font-bold mb-2">For Mentorship</h2>
              <p className="text-sm text-gray-600 mb-4">
                Get questions about mentorship answered quickly by our team. Contact us for quick and
                friendly support.
              </p>
              <div className="space-y-3">
                <input
                  type="text"
                  placeholder="Full Name"
                  className="w-full h-10 rounded-full border border-gray-200 px-4 text-sm outline-none focus:ring-2 focus:ring-emerald-200"
                />
                <input
                  type="email"
                  placeholder="Email"
                  className="w-full h-10 rounded-full border border-gray-200 px-4 text-sm outline-none focus:ring-2 focus:ring-emerald-200"
                />
                <button className="mt-2 px-6 py-2 rounded-full bg-emerald-500 text-white text-sm font-semibold hover:bg-emerald-600">
                  Get Started
                </button>
              </div>
            </div>
          </div>
        </section>
      </main>
    </div>
  );
}
